:root {
  /* Ocean Blue Theme - Simple color palette override */
  --bg-primary: #e6f3ff;
  --bg-alt: #cce7ff;
  --bg-hover: #b3dbff;
  --text-primary: #003d66;
  --text-secondary: #006699;
  --border: #80c9ff;
  --accent: #0080ff;
  --accent-hover: #0066cc;
}

[data-theme="dark"] {
  --bg-primary: #001a33;
  --bg-alt: #002b4d;
  --bg-hover: #003d66;
  --text-primary: #e6f3ff;
  --text-secondary: #b3dbff;
  --border: #004d80;
  --accent: #0080ff;
  --accent-hover: #0099ff;
}

/* Subtle ocean wave effect on cards */
.card {
  background: linear-gradient(135deg, var(--bg-alt) 0%, var(--bg-primary) 100%);
  border-left: 3px solid var(--accent);
}

.card:hover {
  box-shadow: 0 4px 12px rgba(0, 128, 255, 0.2);
}
